+
+// Número de factura SSS-AAAA-NNNNNN (estándar de documentos fiscales del brain de empresa).
+// Fuera de rango es un error: nunca se trunca ni se ajusta.
+export function numeroFactura(sucursal, gestion, correlativo) {
+  const enRango = (valor, min, max) => Number.isInteger(valor) && valor >= min && valor <= max;
+  if (!enRango(sucursal, 1, 999)) throw new RangeError("Sucursal inválida: entero de 1 a 999");
+  if (!enRango(gestion, 1000, 9999)) throw new RangeError("Gestión inválida: año de 4 dígitos");
+  if (!enRango(correlativo, 1, 999999)) throw new RangeError("Correlativo inválido: entero de 1 a 999999");
+  return `${String(sucursal).padStart(3, "0")}-${gestion}-${String(correlativo).padStart(6, "0")}`;
+}
